<template>
  <canvas ref="canvas" class="matrix-canvas" aria-hidden="true" />
</template>

<script lang="ts">
import Vue from 'vue';

const CHARS = '0123456789ｦｧｨｩｪｫｬｭｮｯｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓﾔﾕﾖﾗﾘﾙﾚﾛﾜﾝ';

export default Vue.extend({
  name: 'BackgroundEffect',
  data() {
    return { animId: 0 };
  },
  mounted() {
    this.start();
    window.addEventListener('resize', this.start);
  },
  beforeDestroy() {
    cancelAnimationFrame(this.animId);
    window.removeEventListener('resize', this.start);
  },
  methods: {
    start() {
      cancelAnimationFrame(this.animId);

      const canvas = this.$refs.canvas as HTMLCanvasElement;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      canvas.width  = window.innerWidth;
      canvas.height = window.innerHeight;

      const fontSize = 14;
      const cols     = Math.floor(canvas.width / fontSize);

      // Spread drops across the screen so rain is instant on load
      const drops = Array.from({ length: cols }, () =>
        Math.floor(Math.random() * (canvas.height / fontSize))
      );

      let last = 0;
      const interval = 1000 / 20; // 20 fps — classic Matrix pacing

      const tick = (ts: number) => {
        this.animId = requestAnimationFrame(tick);
        if (ts - last < interval) return;
        last = ts;

        // Fade previous frame to black (creates the trailing glow)
        ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.font = `${fontSize}px 'JetBrains Mono', monospace`;

        for (let i = 0; i < cols; i++) {
          const char = CHARS[Math.floor(Math.random() * CHARS.length)];
          const x    = i * fontSize;
          const y    = drops[i] * fontSize;

          // Bright head character
          ctx.fillStyle = '#00ff41';
          ctx.fillText(char, x, y);

          // Reset column to top after it exits the bottom
          if (y > canvas.height && Math.random() > 0.975) {
            drops[i] = 0;
          }
          drops[i]++;
        }
      };

      this.animId = requestAnimationFrame(tick);
    },
  },
});
</script>

<style scoped>
.matrix-canvas {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}
</style>
